// Welcome screen - Ask user what they want to do
const options = {
  action: 'Please select an action',
  choices: [
    '1. Generate Content Ideas',
    '2. Write Video Script',
    '3. Optimize Video Metadata',
    '4. Complete Content Pipeline (Ideas → Script → Metadata)',
    '5. Generate Thumbnail Concepts'
  ],
  userInput: {
    niche: 'Enter your channel niche/topic',
    targetAudience: 'Enter target audience',
    videoTopic: 'Enter video topic (if applicable)',
    keywords: 'Enter keywords (comma-separated)'
  }
};

return { json: options };

// Process and structure Gemini output
const geminiResponse = $input.item.json.text || $input.item.json.response;

let structured = {};

try {
  // Try to parse as JSON first
  structured = JSON.parse(geminiResponse);
} catch (e) {
  // If not JSON, structure the text response
  structured = {
    rawContent: geminiResponse,
    action: $input.item.json.action || 'Unknown',
    timestamp: new Date().toISOString(),
    processed: true
  };
}

// Add metadata
structured.generatedAt = new Date().toISOString();
structured.aiModel = 'Gemini';
structured.niche = $input.item.json.niche;
structured.targetAudience = $input.item.json.targetAudience;

return { json: structured };

// Format content for Google Drive document
const data = $input.item.json;

let documentContent = '';
let fileName = '';

// Determine document type and format accordingly
if (data.action && data.action.includes('Content Ideas')) {
  fileName = `Content Ideas - ${data.niche} - ${new Date().toISOString().split('T')[0]}.txt`;

  documentContent = `YOUTUBE CONTENT IDEAS\n`;
  documentContent += `Generated: ${data.generatedAt}\n`;
  documentContent += `Niche: ${data.niche}\n`;
  documentContent += `Target Audience: ${data.targetAudience}\n`;
  documentContent += `\n${'='.repeat(80)}\n\n`;

  if (Array.isArray(data.ideas)) {
    data.ideas.forEach((idea, index) => {
      documentContent += `IDEA ${index + 1}: ${idea.title}\n`;
      documentContent += `Description: ${idea.description}\n`;
      documentContent += `Hook: ${idea.hook}\n`;
      documentContent += `Viral Potential: ${idea.viralPotential}/10\n`;
      documentContent += `\n${'-'.repeat(80)}\n\n`;
    });
  } else {
    documentContent += data.rawContent || JSON.stringify(data, null, 2);
  }

} else if (data.action && data.action.includes('Script')) {
  fileName = `Video Script - ${data.videoTitle || 'Untitled'} - ${new Date().toISOString().split('T')[0]}.txt`;

  documentContent = `VIDEO SCRIPT\n`;
  documentContent += `Title: ${data.videoTitle || 'Untitled'}\n`;
  documentContent += `Generated: ${data.generatedAt}\n`;
  documentContent += `\n${'='.repeat(80)}\n\n`;
  documentContent += data.script || data.rawContent || JSON.stringify(data, null, 2);

} else if (data.action && data.action.includes('Metadata')) {
  fileName = `Metadata - ${data.videoTitle || 'Untitled'} - ${new Date().toISOString().split('T')[0]}.txt`;

  documentContent = `VIDEO METADATA OPTIMIZATION\n`;
  documentContent += `Title: ${data.videoTitle || 'Untitled'}\n`;
  documentContent += `Generated: ${data.generatedAt}\n`;
  documentContent += `\n${'='.repeat(80)}\n\n`;

  if (data.optimizedTitles) {
    documentContent += `OPTIMIZED TITLES:\n`;
    data.optimizedTitles.forEach((title, i) => {
      documentContent += `${i + 1}. ${title}\n`;
    });
    documentContent += `\n`;
  }

  if (data.description) {
    documentContent += `DESCRIPTION:\n${data.description}\n\n`;
  }

  if (data.tags) {
    documentContent += `TAGS:\n${data.tags.join(', ')}\n\n`;
  }

  if (data.thumbnailConcepts) {
    documentContent += `THUMBNAIL CONCEPTS:\n`;
    data.thumbnailConcepts.forEach((concept, i) => {
      documentContent += `${i + 1}. ${JSON.stringify(concept, null, 2)}\n`;
    });
  }

  if (!data.optimizedTitles && !data.description && !data.tags) {
    documentContent += data.rawContent || JSON.stringify(data, null, 2);
  }

} else {
  fileName = `YouTube Content - ${new Date().toISOString().split('T')[0]}.txt`;
  documentContent = data.rawContent || JSON.stringify(data, null, 2);
}

return {
  json: {
    ...data,
    fileName: fileName,
    documentContent: documentContent,
    contentType: 'text/plain'
  }
};

// Prepare data for Notion database
const data = $input.item.json;

const notionData = {
  videoTitle: data.videoTitle || data.title || 'Untitled',
  niche: data.niche || 'General',
  targetAudience: data.targetAudience || 'General Audience',
  keywords: data.keywords || [],
  status: 'Draft',
  createdDate: new Date().toISOString(),
  driveUrl: data.driveUrl || '',
  aiModel: data.aiModel || 'Gemini',
  action: data.action || 'Content Created',
  summary: generateSummary(data)
};

function generateSummary(data) {
  if (data.action && data.action.includes('Ideas')) {
    return `Generated ${data.ideas?.length || 'multiple'} content ideas for ${data.niche}`;
  } else if (data.action && data.action.includes('Script')) {
    return `Complete video script created for: ${data.videoTitle}`;
  } else if (data.action && data.action.includes('Metadata')) {
    return `SEO-optimized metadata including title, description, and tags`;
  }
  return 'YouTube content generated by AI agent';
}

return { json: notionData };

// Full pipeline orchestrator
// This runs all steps in sequence: Ideas -> Script -> Metadata

const userInput = $input.item.json;

return {
  json: {
    pipeline: 'full',
    steps: [
      'Generate 5 content ideas',
      'User selects best idea',
      'Generate script for selected idea',
      'Optimize metadata',
      'Save to Drive and Notion',
      'Send notification'
    ],
    userInput: userInput,
    currentStep: 1,
    totalSteps: 6
  }
};

// Error handler and fallback logic
const input = $input.item.json;

if (input.error) {
  return {
    json: {
      status: 'error',
      message: 'An error occurred during processing',
      error: input.error,
      fallbackAction: 'Using OpenAI for retry',
      timestamp: new Date().toISOString()
    }
  };
}

return { json: input };
